928	/**
929	 * @brief 用 EPIC 把整幅画布按当前 rot10 重新烘进 R。
930	 *
931	 * @details 一次约 100 ms（EPIC 任意角旋转的固有代价），所以只在**角度变了 /
932	 *          余量用完 / 整帧结束**时调用；平地跟车只移动 R 的对象。
933	 */
934	static void vmap_rot_full(vmap_view_t * view)
935	{
936	    int32_t pivot_x;
937	    int32_t pivot_y;
938	
939	    if (view == NULL || !view->heading_up || view->rbuf == NULL
940	        || view->cbuf == NULL || view->rcanvas == NULL) {
941	        return;
942	    }
943	
944	    /*
945	     * ⚠ 帧在飞时**绝不能烘**：`vmap_rot_full` 会被 GNSS 定时器经
946	     * `apply_canvas_pos → vmap_rot_track` 调到，而那时正北画布只画了一半瓦片、
947	     * 标签收集器也只填了一部分 ⇒ 烘出来是"半成品"，下一帧再纠正，观感就是
948	     * 地图卡住 + 文字乱跳（2026-10-28 现场）。等 `render_finish` 里再烘。
949	     */
950	    if (view->pump_phase != 0u) {
951	        return;
952	    }
953	
954	    /* 骑手在画布里的位置 = 画布中心 + 跟车 pan。 */
955	    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->pan_dx);
956	    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->pan_dy);
957	    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
958	        pivot_x = view->w / 2;
959	        pivot_y = view->h / 2;
960	    }
961	
962	    if (!myvendor_epic_rotate(view->cbuf, view->stride, view->w, view->h,
963	            view->rbuf, view->rstride, view->rw, view->rh, view->rot10,
964	            pivot_x, pivot_y, view->rw / 2, view->rh / 2)) {
965	        /* 失败：保持上一帧，别把 R 弄脏。 */
966	        return;
967	    }
968	
969	    view->r_pan_x = view->pan_dx;
970	    view->r_pan_y = view->pan_dy;
971	    view->r_rot10 = view->rot10;
972	    vmap_rot_place(view, 0, 0);
973	    vmap_rot_labels_update(view, pivot_x, pivot_y);
974	    lv_obj_invalidate(view->rcanvas);
975	}
