977	/**
978	 * @brief 跟车：R 里的内容该位移 (-R(θ)·Δpan)；余量够只挪对象，不够重烘。
979	 */
980	static void vmap_rot_track(vmap_view_t * view)
981	{
982	    const double th = (double)view->r_rot10 * 0.1 * M_PI / 180.0;
983	    const double c = cos(th);
984	    const double s = sin(th);
985	    const double dpx = view->pan_dx - view->r_pan_x;
986	    const double dpy = view->pan_dy - view->r_pan_y;
987	    const int32_t sx = (int32_t)lround(-(c * dpx - s * dpy));
988	    const int32_t sy = (int32_t)lround(-(s * dpx + c * dpy));
989	    const int32_t lim = view->r_margin - VMAP_PAN_GUARD;
990	
991	    if (view->rot10 != view->r_rot10
992	        || abs((int)sx) > lim || abs((int)sy) > lim) {
993	        vmap_rot_full(view);    /* 角度变了、或余量用完了 */
994	        return;
995	    }
996	
997	    vmap_rot_place(view, sx, sy);
998	}
