1000	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
1001	{
1002	    lv_coord_t px;
1003	    lv_coord_t py;
1004	
1005	    if (!view || !view->canvas) {
1006	        return;
1007	    }
1008	
1009	    px = (lv_coord_t)lround(dx);
1010	    py = (lv_coord_t)lround(dy);
1011	
1012	    if (px == view->last_pan_px && py == view->last_pan_py) {
1013	        return;
1014	    }
1015	
1016	    /*
1017	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
1018	     * GNSS movement; the centered arrow still updates normally.
1019	     */
1020	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
1021	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
1022	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
1023	        return;
1024	    }
1025	
1026	    view->pan_dx = (double)px;
1027	    view->pan_dy = (double)py;
1028	    view->last_pan_px = px;
1029	    view->last_pan_py = py;
1030	    view->map_rev++;
1031	    vmap_label_collector_set_focus(&view->label_col,
1032	        view->w / 2 + px, view->h / 2 + py);
1033	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
1034	    bicycle_inval_probe_tag("vmap_pan");
1035	#endif
1036	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
1037	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
1038	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
1039	    if (!view->heading_up) {
1040	        lv_obj_set_pos(view->canvas,
1041	            (lv_coord_t)(-view->margin - px),
1042	            (lv_coord_t)(-view->margin - py + view->y_bias));
1043	        return;
1044	    }
1045	
1046	    /*
1047	     * 航向朝上：不再让 LVGL 旋转画布（那样每次平移都要重跑一次任意角 transform，
1048	     * 实测 60 ms/次）。改成维护一块**屏幕对齐的旋转缓冲 R**：只有角度变化或
1049	     * 余量用完才重烘，平地跟车只移动 R 的对象（见 vmap_rot_track）。
1050	     */
1051	    vmap_rot_track(view);
1052	}
