1054	/**
1055	 * @brief 航向朝上：地图跟随骑行方向旋转（箭头恒指上）。
1056	 */
1057	void vmap_view_set_heading_up(vmap_view_t * view, bool enable)
1058	{
1059	    if (!view || view->heading_up == enable) {
1060	        return;
1061	    }
1062	
1063	    if (enable && (view->rcanvas == NULL || view->rbuf == NULL)) {
1064	        syslog(LOG_WARNING,
1065	            "[map] heading-up refused: rotated buffer unavailable\n");
1066	        return;
1067	    }
1068	
1069	    view->heading_up = enable;
1070	    view->heading_valid = false;
1071	    view->rot10 = 0;
1072	    view->r_rot10 = -1;         /* 强制下一次 track 重烘 */
1073	
1074	    if (enable) {
1075	        if (view->rcanvas) {
1076	            lv_obj_clear_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
1077	        }
1078	        if (view->canvas) {
1079	            lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
1080	        }
1081	        if (view->render_rev != 0u) {
1082	            vmap_rot_full(view);    /* 画布已有内容才值得烘 */
1083	        }
1084	    } else {
1085	        if (view->rcanvas) {
1086	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
1087	        }
1088	        if (view->canvas) {
1089	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
1090	        }
1091	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
1092	        {
1093	            int32_t i;
1094	
1095	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
1096	                if (view->rot_label[i] != NULL) {
1097	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
1098	                }
1099	            }
1100	            view->rot_label_n = 0;
1101	        }
1102	    }
1103	
1104	    /* 位置公式与标签开关都变了：按新公式重摆，再整幅重来一帧。 */
1105	    view->last_pan_px = INT32_MIN;
1106	    view->last_pan_py = INT32_MIN;
1107	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
1108	    syslog(LOG_NOTICE, "[map] heading-up %s\n", enable ? "on" : "off");
1109	
1110	    /* 首帧之前不要提前开帧（开机还没进过地图时由页面层控制）。 */
1111	    if (view->render_rev != 0u) {
1112	        vmap_view_render(view);
1113	    }
1114	}
