1147	/**
1148	 * @brief 更新航向（0–360，正北 0，顺时针）与当前速度。
1149	 */
1150	void vmap_view_set_heading(vmap_view_t * view, float heading_deg, float speed_kph)
1151	{
1152	    double d = (double)heading_deg;
1153	    int32_t target;
1154	    int32_t delta;
1155	
1156	    if (!view || !view->heading_up || !view->canvas) {
1157	        return;
1158	    }
1159	    if (!(d >= 0.0) || !(d < 360.0)) {
1160	        return;                 /* NaN / 越界：宁可不转 */
1161	    }
1162	
1163	    if (!view->heading_valid) {
1164	        /* 首个航向无条件接受：否则停车时箭头指上、地图还是正北。 */
1165	        view->heading_deg = d;
1166	        view->heading_valid = true;
1167	    } else if (speed_kph >= VMAP_ROT_MIN_KPH) {
1168	        double diff = d - view->heading_deg;
1169	
1170	        /* 圆周低通：先把差值折到 -180..180，避免 359°→1° 绕一整圈。 */
1171	        while (diff > 180.0) {
1172	            diff -= 360.0;
1173	        }
1174	        while (diff < -180.0) {
1175	            diff += 360.0;
1176	        }
1177	        view->heading_deg += diff * (double)VMAP_ROT_SMOOTH;
1178	        while (view->heading_deg >= 360.0) {
1179	            view->heading_deg -= 360.0;
1180	        }
1181	        while (view->heading_deg < 0.0) {
1182	            view->heading_deg += 360.0;
1183	        }
1184	    } else {
1185	        return;                 /* 低速：course 是噪声，保持上次朝向 */
1186	    }
1187	
1188	    /* 航向朝上 ⇒ 地图转 -heading（顺时针为正）。 */
1189	    target = ((int32_t)lround(-view->heading_deg * 10.0) % 3600 + 3600) % 3600;
1190	    delta = ((target - view->rot10 + 3600 + 1800) % 3600) - 1800;
1191	    if (abs((int)delta) < VMAP_ROT_STEP_10) {
1192	        return;
1193	    }
1194	
1195	    /*
1196	     * 重烘限频：每烘一次 ~155 ms（EPIC 任意角 0.8 Mpx/s）。1° 步进时若不限频，
1197	     * 3.6°/s 的弯道会有 3~4 次/秒（≈50% UI）。这里最多 2 次/秒 —— 转弯时地图
1198	     * 比真实航向慢半拍，单步会放大到 ~2°（用户 2026-10-28 接受"旋转慢一些"）。
1199	     */
1200	    if (view->last_bake_ms != 0u
1201	        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
1202	        return;                 /* rot10 不动：角度继续累计，下次一次转到位 */
1203	    }
1204	    view->last_bake_ms = lv_tick_get();
1205	
1206	    view->rot10 = target;
1207	
1208	    /* 角度变了 ⇒ R 的整幅内容作废，交给 vmap_rot_track 重烘（见它的条件）。 */
1209	    view->last_pan_px = INT32_MIN;
1210	    view->last_pan_py = INT32_MIN;
1211	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
1212	}
