2724	bool vmap_view_render_pump(vmap_view_t * view, unsigned max_tiles)
2725	{
2726	    unsigned n;
2727	    uint32_t t0;
2728	
2729	    if (!view || !view->canvas || !view->cbuf || myvendor_mtp_lfs_quiesce()) {
2730	        return true;
2731	    }
2732	
2733	    if (view->pump_phase == 0) {
2734	        /* 没有帧在飞 ⇒ 泵本来就不该被调用（帧结束后定时器自己暂停）。
2735	         * **基准必须作废**，否则下一帧的第一拍会把"这一整段空闲"算成"UI 线程被占住"
2736	         * —— 第一版就是这么误报的：`SLOW pump gap 9471ms` / `2228ms` 其实都是
2737	         * "这段时间没渲染"（同期 BLE 每 10 秒的心跳照打，证明系统是活的）。 */
2738	        s_pf_last_pump_cyc = 0u;
2739	        return true;
2740	    }
2741	
2742	    if (max_tiles == 0) {
2743	        max_tiles = VMAP_RENDER_PUMP_MAX_TILES;
2744	    }
2745	
2746	    t0 = lv_tick_get();
2747	    myvendor_watchdog_ui_beat();
2748	    /* 单拍间隔超长 ⇒ **无条件** WARNING（正常帧不受影响）。只在这一帧确实在飞时量，
2749	     * 所以"没渲染的空闲"不会被算进来；而帧内一次 2 秒以上的拍间隔就只能是系统级
2750	     * 停顿（现场两次 WDT 饥饿复位都伴随 1.6~12 秒的这类间隔，且当时 [vperf] 正被
2751	     * 降到 debug、整场不可诊断）。 */
2752	    {
2753	        const uint32_t now_cyc = vmap_perf_cyc();
2754	
2755	        if (s_pf_last_pump_cyc != 0u && now_cyc - s_pf_last_pump_cyc
2756	            > VMAP_PERF_SLOW_GAP_MS * 240u * 1000u) {
2757	            syslog(LOG_WARNING,
2758	                "[vperf] SLOW pump gap %ums (>%ums) —— 帧内拍间隔异常，UI 线程被占住；若同时 WDT 停喂即饥饿族",
2759	                (unsigned)((now_cyc - s_pf_last_pump_cyc) / 240000u),
2760	                (unsigned)VMAP_PERF_SLOW_GAP_MS);
2761	            vmap_perf_dump_runnable();
2762	        }
2763	        s_pf_last_pump_cyc = now_cyc;
2764	    }
2765	
2766	    for (n = 0; n < max_tiles && view->pump_phase != 0; n++) {
2767	        if (n > 0 && lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
2768	            break;
2769	        }
2770	        if (!render_next_tile(view)) {
2771	            render_finish(view);
2772	            break;
2773	        }
2774	        if (lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
2775	            break;
2776	        }
2777	    }
2778	
2779	    return view->pump_phase == 0;
2780	}
