                score += fmin(VMAP_NAV_MATCH_MAX_PENALTY,
                    excess * VMAP_NAV_MATCH_PROGRESS_W);
            }

            if (score < best_score) {
                best_score = score;
                best_d = d;
                seg = i;
                best_seg_start_m = acc;
                best_t = tloc;
                best_along = candidate_along;
            }
            acc += seg_m;
