            + (s * dx + c * dy));
        const int32_t sx = rx - view->r_margin;
        const int32_t sy = ry - view->r_margin;          /* 不含 y_bias */
        const int32_t sy_vis = sy + view->y_bias;        /* 只用于裁剪判断 */
        lv_obj_t * l;
