void vmap_view_destroy(vmap_view_t * view)
{
    if (!view) {
        return;
    }

    /* 动画回调以 view 为 var，必须先停，避免 view 释放后回调访问野指针。 */
    lv_anim_delete(view, vmap_arrow_angle_exec);

