        lv_obj_delete(view->arrow);
    }
    if (view->rcanvas) {
        lv_obj_delete(view->rcanvas);
        view->rcanvas = NULL;
    }
    if (view->rbuf) {
        vmap_free(view->rbuf);
        view->rbuf = NULL;
    }
    if (view->cbuf && !view->cbuf_arena) {
        vmap_free(view->cbuf);
    }
    if (view->scratch) {
        vmap_free(view->scratch);
    }
    if (view->labels) {
        vmap_free(view->labels);
    }
    if (view->label_retained) {
