bool vmap_view_geo_to_viewport_raw(const vmap_view_t * view, double lon, double lat,
    int32_t * out_x, int32_t * out_y)
{
    return vmap_view_geo_to_viewport_impl(view, lon, lat, out_x, out_y, false);
}

