#include <stdio.h>
#include <math.h>
#include "vmap_geo.c"

/* 参考 1：同一局部平面但用精确 cos(lat) —— 只衡量多项式近似带来的误差。 */
static double ref_plane(double px, double py, double ax, double ay,
                        double bx, double by, double * t_out)
{
    const double kx = 111320.0 * cos(ay * M_PI / 180.0);
    const double vx = (bx - ax) * kx;
    const double vy = (by - ay) * VMAP_GEO_M_PER_DEG_LAT;
    const double wx = (px - ax) * kx;
    const double wy = (py - ay) * VMAP_GEO_M_PER_DEG_LAT;
    const double seg2 = vx * vx + vy * vy;
    double t = 0.0;
    if (seg2 > 1e-6) {
        t = (wx * vx + wy * vy) / seg2;
        if (t < 0) t = 0; else if (t > 1) t = 1;
    }
    if (t_out) *t_out = t;
    {
        const double dx = wx - vx * t;
        const double dy = wy - vy * t;
        return sqrt(dx * dx + dy * dy);
    }
}

/* 参考 2：逐段 haversine + 方位角（改动前的做法；慢但在球面上是"对"的）。 */
static double ref_sphere(double px, double py, double ax, double ay,
                         double bx, double by, double * t_out)
{
    const double seg_m = vmap_geo_haversine_m(ax, ay, bx, by);
    const float brg = vmap_geo_bearing_deg(ax, ay, bx, by);
    const float brg_p = vmap_geo_bearing_deg(ax, ay, px, py);
    const double ap_m = vmap_geo_haversine_m(ax, ay, px, py);
    double t = 0.0;

    if (seg_m < 0.5) {
        if (t_out) *t_out = 0.0;
        return ap_m;
    }
    {
        const double along = ap_m * cos((brg_p - brg) * M_PI / 180.0);
        t = along / seg_m;
        if (t < 0.0) t = 0.0; else if (t > 1.0) t = 1.0;
    }
    if (t_out) *t_out = t;
    {
        const double r = ap_m * ap_m - (along * along);
        return sqrt(r > 0.0 ? r : 0.0);
    }
}

